# claude-mem NOBETCISI - oturum basinda oksuz surecleri temizler.
#
# NEDEN VAR (2026-09-01):
#   claude-mem'in worker'i acilirken once dosyalari onbellege aliyor,
#   sonra chroma'yi baslatiyor, EN SON portu (37777) aciyor. Onceki
#   kosumdan kalan bir chroma sureci (uv onbelleginden calisan
#   python.exe) hayattaysa yeni worker o adimda TAKILIYOR ve port hic
#   acilmiyor. Gunlukteki belirtisi:
#       Worker port did not open after lazy-spawn within the cold-boot wait
#   Bu, Claude Code zorla kapatildiginda (cokme, gorev yoneticisi)
#   olusuyor ve sonucu SESSIZ: hicbir sey bloke olmuyor ama hafiza
#   kayit tutmayi birakiyor.
#
# NE YAPAR:
#   1. Port 37777 saglikliysa HICBIR SEY yapmaz - calisan bir worker'a
#      dokunmak en kotu sonucu verirdi.
#   2. Saglik yoksa, claude-mem'e ait ESKI surecleri (60 saniyeden
#      once baslamis bun ve uv-chroma python surecleri) sonlandirir.
#      60 saniye siniri onemli: o an ACILMAKTA olan bir worker'i
#      oldurmemek icin. Yeni baslamis surece dokunulmuyor.
#
# NEDEN HER ZAMAN 0 DONER:
#   Bu hook'un kendisi oturumu bloke edemez. claude-mem 2026-08-19'da
#   tam olarak "hook basarisiz olunca kullanicinin mesajini bloke etme"
#   yuzunden kapatilmisti; onu onlemek icin yazilan bir hook'un ayni
#   hataya dusmesi kabul edilemez. Hatalar YUTULMUYOR, ekrana yaziliyor
#   - yalnizca cikis kodu 0 kaliyor.

$ErrorActionPreference = 'Continue'

function Saglikli {
    try {
        $c = Invoke-WebRequest -Uri 'http://127.0.0.1:37777/health' -TimeoutSec 2 -UseBasicParsing
        return $c.StatusCode -eq 200
    } catch { return $false }
}

try {
    if (Saglikli) {
        Write-Output 'claude-mem: worker saglikli, dokunulmadi.'
        exit 0
    }

    $esik = (Get-Date).AddSeconds(-60)
    $oldurulen = 0

    # 1) Eski bun surecleri (claude-mem worker'i bun ile calisiyor).
    Get-Process bun -ErrorAction SilentlyContinue | ForEach-Object {
        try {
            if ($_.StartTime -lt $esik) { Stop-Process -Id $_.Id -Force; $oldurulen++ }
        } catch { Write-Output "claude-mem: bun $($_.Id) sonlandirilamadi: $($_.Exception.Message)" }
    }

    # 2) Eski chroma surecleri. Olcut KOMUT SATIRI: kullanicinin kendi
    #    python islerine dokunmamak icin yalnizca uv onbelleginden
    #    calisanlar sonlandiriliyor.
    Get-CimInstance Win32_Process -Filter "Name='python.exe'" -ErrorAction SilentlyContinue |
        Where-Object { $_.CommandLine -like '*uv*archive*' } |
        ForEach-Object {
            try {
                $p = Get-Process -Id $_.ProcessId -ErrorAction SilentlyContinue
                if ($p -and $p.StartTime -lt $esik) { Stop-Process -Id $_.ProcessId -Force; $oldurulen++ }
            } catch { Write-Output "claude-mem: chroma $($_.ProcessId) sonlandirilamadi: $($_.Exception.Message)" }
        }

    if ($oldurulen -gt 0) {
        Write-Output "claude-mem: $oldurulen oksuz surec temizlendi; worker ilk mesajda yeniden acilacak."
    } else {
        Write-Output 'claude-mem: worker kapali ama temizlenecek oksuz surec yok.'
    }
} catch {
    Write-Output "claude-mem nobetcisi hata verdi (oturum etkilenmedi): $($_.Exception.Message)"
}

exit 0

